                } catch (final SocketException | InterruptedIOException e) {
                    if (++timeouts >= maxTimeouts) {
                        throw new IOException("Connection timed out.");
                    }
                } catch (final TFTPPacketException e) {
                    throw new IOException("Bad packet: " + e.getMessage());
                }
