        }
        throw ioe;
    } finally {

        if (printHash) {
            System.err.println();
        }

        if (mboxListener != null) {
            mboxListener.close();
            final Iterator<String> missingIds = mboxListener.missingIds.iterator();
            if (missingIds.hasNext()) {
                final StringBuilder sb = new StringBuilder();
                for(;;) {
                    sb.append(missingIds.next());
                    if (!missingIds.hasNext()) {
