        final Matcher m = Pattern.compile("(imaps?://[^/]+)(/.*)").matcher(uriString);
        if (m.matches()) {
            uri = URI.create(m.group(1)); // Just the scheme and auth parts
            uri = new URI(uri.getScheme(), uri.getAuthority(), m.group(2), null, null);
        } else {
            throw e;
        }
    }
