public String toString()
{
    final StringBuilder header = new StringBuilder();

    header.append("From: ");
    header.append(from);
    header.append("\nNewsgroups: ");
    header.append(newsgroups.toString());
    header.append("\nSubject: ");
    header.append(subject);
